// n8n Code node: enter_compound
// Workflow: peptide_caption_gen
// Mode: Run Once for All Items
// Settings → Execute Once = OFF
// After: manual_trigger
// Before: get_caption_science
//
// TYPE THE CATALOG NAME HERE, then Execute workflow.

var COMPOUND = 'BPC-157';

return [
  {
    json: {
      compound_name_input: String(COMPOUND || '').trim(),
    },
  },
];

// n8n Code node: match_compound
// Workflow: peptide_caption_gen
// Mode: Run Once for All Items
// Settings → Execute Once = OFF (must see all Sheet 15 rows)
// After: get_caption_science
// Before: build_captions

function val(obj, names, fallback) {
  if (fallback === undefined) fallback = '';
  for (var i = 0; i < names.length; i++) {
    var n = names[i];
    if (obj[n] !== undefined && obj[n] !== null && String(obj[n]).trim() !== '') {
      return obj[n];
    }
  }
  return fallback;
}

function norm(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/\+/g, 'plus')
    .replace(/[^a-z0-9]+/g, '');
}

function firstJson(name) {
  try {
    return $(name).first().json || {};
  } catch (e) {
    return {};
  }
}

function lev(a, b) {
  a = String(a || '');
  b = String(b || '');
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  var m = [];
  for (var i = 0; i <= b.length; i++) m[i] = [i];
  for (var j = 0; j <= a.length; j++) m[0][j] = j;
  for (i = 1; i <= b.length; i++) {
    for (j = 1; j <= a.length; j++) {
      m[i][j] =
        b.charAt(i - 1) === a.charAt(j - 1)
          ? m[i - 1][j - 1]
          : Math.min(m[i - 1][j - 1] + 1, m[i][j - 1] + 1, m[i - 1][j] + 1);
    }
  }
  return m[b.length][a.length];
}

var wantedRaw = String(firstJson('enter_compound').compound_name_input || '').trim();
if (!wantedRaw) {
  throw new Error('enter_compound is empty. Type a catalog name (example: BPC-157).');
}

var rows = $input.all().map(function (i) {
  return i.json;
});
if (rows.length < 2) {
  throw new Error(
    'match_compound saw ' +
      rows.length +
      ' sheet row(s). Execute Once must be OFF. Import tab 15-caption-science-27.'
  );
}

var wanted = norm(wantedRaw);
var scored = [];

rows.forEach(function (r) {
  var name = String(val(r, ['compound_name'], '')).trim();
  if (!name) return;
  var aliases = String(val(r, ['aliases'], ''))
    .split(',')
    .map(function (a) {
      return norm(a);
    })
    .filter(Boolean);
  var keys = [norm(name)].concat(aliases);
  var best = 99;
  keys.forEach(function (k) {
    if (!k) return;
    if (k === wanted) best = 0;
    else if (k.indexOf(wanted) !== -1 || wanted.indexOf(k) !== -1) best = Math.min(best, 1);
    else best = Math.min(best, lev(k, wanted));
  });
  scored.push({ row: r, name: name, dist: best });
});

scored.sort(function (a, b) {
  return a.dist - b.dist;
});

var hit = scored[0];
if (!hit || hit.dist > 2) {
  var suggest = scored
    .slice(0, 5)
    .map(function (s) {
      return s.name;
    })
    .join(', ');
  throw new Error(
    'No catalog match for "' +
      wantedRaw +
      '". Closest: ' +
      suggest +
      '. Use an exact Sheet 15 compound_name.'
  );
}

var r = hit.row;
return [
  {
    json: {
      compound_name: hit.name,
      compound_name_input: wantedRaw,
      match_distance: hit.dist,
      compound_id: val(r, ['compound_id']),
      aliases: val(r, ['aliases']),
      science_what: val(r, ['science_what']),
      science_focus: val(r, ['science_focus']),
      science_pathways: val(r, ['science_pathways']),
      tag2: val(r, ['tag2']),
      tag3: val(r, ['tag3']),
      tag4: val(r, ['tag4']),
      tag5: val(r, ['tag5']),
      store_url: val(r, ['store_url']) || 'www.palmbeach-vitality.store',
      input_row_count: rows.length,
    },
  },
];

// n8n Code node: build_captions
// Workflow: peptide_caption_gen
// Mode: Run Once for All Items
// After: match_compound
// Before: verify_fda_captions
//
// 2 vial + 2 pen captions. Same science, different product-form language.

function firstJson(name) {
  try {
    return $(name).first().json || {};
  } catch (e) {
    return {};
  }
}

function toHashtag(name) {
  var raw = String(name || '')
    .replace(/\+/g, 'Plus')
    .replace(/[^a-zA-Z0-9]+/g, '');
  return raw ? '#' + raw : '#PeptideResearch';
}

var m = firstJson('match_compound');
var name = String(m.compound_name || '').trim();
if (!name) throw new Error('build_captions: compound_name missing from match_compound.');

var what = String(m.science_what || '').trim();
var focus = String(m.science_focus || '').trim();
var pathways = String(m.science_pathways || '').trim();
var url = String(m.store_url || 'www.palmbeach-vitality.store').trim();

var tags = [
  toHashtag(name),
  '#' + String(m.tag2 || 'PeptideResearch').replace(/^#/, ''),
  '#' + String(m.tag3 || 'CellularScience').replace(/^#/, ''),
  '#' + String(m.tag4 || 'PeptideScience').replace(/^#/, ''),
  '#' + String(m.tag5 || 'ResearchPeptides').replace(/^#/, ''),
].join(' ');

function pack(body, cta) {
  return (body + '\n' + cta + '\n' + tags).replace(/\s+\n/g, '\n').trim();
}

var vialCtaA = 'Explore research-grade ' + name + ' in the 10ml laboratory vial catalog at ' + url;
var vialCtaB = 'Browse the 10ml research vial listing for ' + name + ' at ' + url;
var penCtaA = 'Explore research-grade ' + name + ' in the 3ml research pen catalog at ' + url;
var penCtaB = 'Browse the 3ml research pen listing for ' + name + ' at ' + url;

var vial1 = pack(
  name + ' is ' + what + '. Research focuses on ' + focus + '.',
  vialCtaA
);
var vial2 = pack(
  name + ' is studied as ' + what + '. Laboratory work examines ' + pathways + '.',
  vialCtaB
);
var pen1 = pack(
  name + ' is ' + what + '. Research focuses on ' + focus + '.',
  penCtaA
);
var pen2 = pack(
  name + ' is studied as ' + what + '. Laboratory work examines ' + pathways + '.',
  penCtaB
);

return [
  {
    json: {
      compound_name: name,
      compound_name_input: m.compound_name_input,
      match_distance: m.match_distance,
      compound_id: m.compound_id,
      store_url: url,
      hashtag_line: tags,
      vial_caption_1: vial1,
      vial_caption_2: vial2,
      pen_caption_1: pen1,
      pen_caption_2: pen2,
      input_row_count: m.input_row_count,
    },
  },
];

// n8n Code node: verify_fda_captions
// Workflow: peptide_caption_gen
// Mode: Run Once for All Items
// After: build_captions
// Before: prep_caption_email
//
// Throws if a caption would trip human-use / benefit / typo checks.
// Linear: fail = stop. Pass = email.

function firstJson(name) {
  try {
    return $(name).first().json || {};
  } catch (e) {
    return {};
  }
}

var BANNED = [
  'human use',
  'not for human',
  'for humans',
  'human consumption',
  'benefits of using',
  'benefit of',
  'you will',
  'you\'ll',
  'lose weight',
  'fat loss',
  'anti-aging results',
  'treats',
  'treat your',
  'cure',
  'heals',
  'healing you',
  'therapy',
  'patient',
  'clinical use',
  'fda approved',
  'inject',
  'injection',
  'syringe',
  'dose',
  'dosage',
  'mg/ml',
  'take daily',
  'recommended for',
  'supplement',
  'buy to use',
  'works for',
  'guaranteed',
];

var b = firstJson('build_captions');
var name = String(b.compound_name || '').trim();
var captions = [
  { key: 'vial_caption_1', text: String(b.vial_caption_1 || ''), form: 'vial' },
  { key: 'vial_caption_2', text: String(b.vial_caption_2 || ''), form: 'vial' },
  { key: 'pen_caption_1', text: String(b.pen_caption_1 || ''), form: 'pen' },
  { key: 'pen_caption_2', text: String(b.pen_caption_2 || ''), form: 'pen' },
];

var errors = [];

captions.forEach(function (c) {
  if (!c.text) {
    errors.push(c.key + ' is empty');
    return;
  }
  var low = c.text.toLowerCase();
  if (c.text.indexOf(name) !== 0 && low.indexOf(name.toLowerCase()) === -1) {
    errors.push(c.key + ' must name ' + name);
  }
  BANNED.forEach(function (w) {
    if (low.indexOf(w) !== -1) errors.push(c.key + ' flagged: "' + w + '"');
  });
  var hashLines = c.text.split('\n').filter(function (ln) {
    return ln.indexOf('#') !== -1;
  });
  var last = hashLines[hashLines.length - 1] || '';
  var tags = last.match(/#[A-Za-z0-9]+/g) || [];
  if (tags.length !== 5) errors.push(c.key + ' needs exactly 5 hashtags, found ' + tags.length);
  var wantFirst = '#' + name.replace(/\+/g, 'Plus').replace(/[^a-zA-Z0-9]+/g, '');
  if (tags[0] && tags[0].toLowerCase() !== wantFirst.toLowerCase()) {
    errors.push(c.key + ' first hashtag must be ' + wantFirst + ' (got ' + tags[0] + ')');
  }
  if (c.text.indexOf('www.palmbeach-vitality.store') === -1) {
    errors.push(c.key + ' missing store URL');
  }
  if (c.form === 'vial' && !/10ml|vial/i.test(c.text)) {
    errors.push(c.key + ' must mention the 10ml vial catalog');
  }
  if (c.form === 'pen' && !/3ml|research pen/i.test(c.text)) {
    errors.push(c.key + ' must mention the 3ml research pen catalog');
  }
});

if (vialLooksLikePen(b.vial_caption_1) || vialLooksLikePen(b.vial_caption_2)) {
  errors.push('vial caption accidentally reads as a pen listing');
}
if (penLooksLikeVial(b.pen_caption_1) || penLooksLikeVial(b.pen_caption_2)) {
  errors.push('pen caption accidentally reads as a vial listing');
}

function vialLooksLikePen(t) {
  return /3ml research pen/i.test(String(t || '')) && !/10ml/i.test(String(t || ''));
}
function penLooksLikeVial(t) {
  return /10ml laboratory vial|10ml research vial/i.test(String(t || '')) && !/3ml/i.test(String(t || ''));
}

if (errors.length) {
  throw new Error('Caption verify failed:\n- ' + errors.join('\n- '));
}

return [
  {
    json: {
      compound_name: name,
      compound_name_input: b.compound_name_input,
      match_distance: b.match_distance,
      compound_id: b.compound_id,
      store_url: b.store_url,
      hashtag_line: b.hashtag_line,
      vial_caption_1: b.vial_caption_1,
      vial_caption_2: b.vial_caption_2,
      pen_caption_1: b.pen_caption_1,
      pen_caption_2: b.pen_caption_2,
      verify_status: 'accepted',
      created_at: new Date().toISOString(),
      input_row_count: b.input_row_count,
    },
  },
];

// n8n Code node: prep_caption_email
// Workflow: peptide_caption_gen
// Mode: Run Once for All Items
// After: verify_fda_captions
// Before: sheets_append_captions → gmail_send_captions

function firstJson(name) {
  try {
    return $(name).first().json || {};
  } catch (e) {
    return {};
  }
}

var v = firstJson('verify_fda_captions');
var name = String(v.compound_name || '').trim();
if (String(v.verify_status || '') !== 'accepted') {
  throw new Error('prep_caption_email: captions were not accepted.');
}

var body = [
  name + ' captions — verified (research language only)',
  '',
  'Resolved from: ' + String(v.compound_name_input || name),
  'Match distance: ' + String(v.match_distance),
  '',
  '—— VIAL 1 ——',
  v.vial_caption_1,
  '',
  '—— VIAL 2 ——',
  v.vial_caption_2,
  '',
  '—— PEN 1 ——',
  v.pen_caption_1,
  '',
  '—— PEN 2 ——',
  v.pen_caption_2,
  '',
  'Copy one block into IG. Logo / extra text / sound stay off the Grok clip.',
].join('\n');

return [
  {
    json: {
      compound_name: name,
      compound_id: v.compound_id,
      compound_name_input: v.compound_name_input,
      match_distance: v.match_distance,
      store_url: v.store_url,
      hashtag_line: v.hashtag_line,
      vial_caption_1: v.vial_caption_1,
      vial_caption_2: v.vial_caption_2,
      pen_caption_1: v.pen_caption_1,
      pen_caption_2: v.pen_caption_2,
      verify_status: v.verify_status,
      created_at: v.created_at,
      caption_run_id: 'CAP-' + name.replace(/[^a-zA-Z0-9]+/g, '') + '-' + Date.now(),
      email_to: 'salvatorejohnson1984@gmail.com',
      email_cc: 'sales@palmbeach-vitality.com',
      email_subject: 'PB Vitality captions — ' + name + ' (vial + pen)',
      email_body: body,
    },
  },
];
